def inside(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except ValueError:
        return False


def target_path(relative: Path) -> Path:
    if relative not in TARGETS:
        raise RuntimeError(f"Refusing non-target path: {relative}")
    path = (PROJECT / relative).resolve()
    if not inside(path, PROJECT):
        raise RuntimeError(f"Target escapes project root: {relative}")
    return path


def require_project_root() -> None:
    if Path.cwd().resolve() != PROJECT.resolve():
        raise RuntimeError(f"Run this installer from the RareIQ root: {PROJECT}")
    for required in (PROJECT / "app.py", PROJECT / "rareiq/version.py", PROJECT / ".git"):
        if not required.exists():
            raise RuntimeError(f"Not a RareIQ checkout; missing {required}")


def verify_markers(markers: dict[Path, tuple[str, ...]]) -> None:
    for relative, expected in markers.items():
        path = target_path(relative)
        if not path.is_file():
            raise RuntimeError(f"Missing target: {relative}")
        content = path.read_text(encoding="utf-8")
        missing = [marker for marker in expected if marker not in content]
        if missing:
            raise RuntimeError(f"Unexpected contents in {relative}: {missing}")


def verify_pre_update() -> None:
    if target_path(TARGETS[-1]).exists():
        raise RuntimeError("Update 13 test already exists; expected clean v6.4.12.")
    verify_markers(PRE_UPDATE_MARKERS)


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def create_backup() -> Path:
    backup = BACKUP_ROOT / datetime.now().strftime("update_13_%Y%m%d_%H%M%S")
    if not inside(backup, PROJECT):
        raise RuntimeError("Backup path escapes project root.")
    backup.mkdir(parents=True, exist_ok=False)
    records = []
    for relative in TARGETS:
        source = target_path(relative)
        record = {"path": relative.as_posix(), "existed": source.exists()}
        if source.exists():
            saved = backup / relative
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, saved)
            record["sha256"] = sha256(saved)
        records.append(record)
    (backup / MANIFEST_NAME).write_text(
        json.dumps({"project": str(PROJECT.resolve()), "files": records}, indent=2),
        encoding="utf-8",
    )
    return backup


def validated_backup(path: Path) -> tuple[Path, list[dict[str, object]]]:
    backup = path.resolve()
    if not inside(backup, BACKUP_ROOT) or backup == BACKUP_ROOT.resolve():
        raise RuntimeError("Rollback path is outside timestamped Update 13 backups.")
    manifest = backup / MANIFEST_NAME
    if not manifest.is_file():
        raise RuntimeError("Update 13 rollback manifest is missing.")
    records = json.loads(manifest.read_text(encoding="utf-8")).get("files")
    expected = {path.as_posix() for path in TARGETS}
    actual = {str(item.get("path")) for item in records if isinstance(item, dict)}
    if actual != expected:
        raise RuntimeError("Rollback manifest does not match the Update 13 allowlist.")
    return backup, records


def restore_backup(path: Path) -> None:
    backup, records = validated_backup(path)
    for record in records:
        relative = Path(str(record["path"]))
        destination = target_path(relative)
        if bool(record.get("existed")):
            source = (backup / relative).resolve()
            if not inside(source, backup) or not source.is_file():
                raise RuntimeError(f"Invalid rollback source: {source}")
            if sha256(source) != str(record.get("sha256") or ""):
                raise RuntimeError(f"Rollback checksum failed: {relative}")
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, destination)
        elif destination.exists():
            destination.unlink()


def install_payload() -> None:
    if set(PAYLOAD) != set(TARGETS):
        raise RuntimeError("Embedded payload does not match the Update 13 allowlist.")
    for relative, encoded in PAYLOAD.items():
        destination = target_path(relative)
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(gzip.decompress(base64.b64decode(encoded)))
    artwork = target_path(Path("rareiq/services/artwork_index_service.py"))
    content = artwork.read_text(encoding="utf-8")
    content = content.replace(
        '0.25 * float(match["hash_score"])\n'
        '                    + 0.75 * float(evidence["verification_score"])',
        '0.40 * float(match["hash_score"])\n'
        '                    + 0.60 * float(evidence["verification_score"])',
    )
    artwork.write_text(content, encoding="utf-8")


def compile_python(backup: Path) -> None:
    compile_dir = backup / "compile"
    compile_dir.mkdir(parents=True, exist_ok=True)
    for index, relative in enumerate(PYTHON_TARGETS):
        py_compile.compile(
            str(target_path(relative)),
            cfile=str(compile_dir / f"{index}.pyc"),
            doraise=True,
        )


def run_targeted_tests() -> None:
    environment = dict(os.environ)
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    subprocess.run(
        [sys.executable, "-B", "-m", "pytest", "-q", "-p", "no:cacheprovider", *TARGETED_TESTS],
        cwd=PROJECT,
        env=environment,
        check=True,
    )


def main() -> int:
    parser = argparse.ArgumentParser(description="Install RareIQ 6.4 Update 13.")
    parser.add_argument("--rollback", type=Path)
    parser.add_argument("--verify-only", action="store_true")
    parser.add_argument("--simulate-test-failure", action="store_true", help=argparse.SUPPRESS)
    args = parser.parse_args()
    backup = None
    try:
        require_project_root()
        if args.rollback:
            restore_backup(args.rollback)
            print(f"RareIQ Update 13 rollback complete: {args.rollback.resolve()}")
            return 0
        if args.verify_only:
            verify_markers(POST_UPDATE_MARKERS)
            print("RareIQ 6.4 Update 13 contracts verified.")
            return 0
        verify_pre_update()
        backup = create_backup()
        install_payload()
        verify_markers(POST_UPDATE_MARKERS)
        compile_python(backup)
        run_targeted_tests()
        if args.simulate_test_failure:
            raise RuntimeError("Simulated post-test failure for rollback validation.")
    except Exception as exc:
        if backup is not None:
            try:
                restore_backup(backup)
                print(f"Automatic rollback restored: {backup}", file=sys.stderr)
            except Exception as rollback_error:
                print(f"AUTOMATIC ROLLBACK FAILED: {rollback_error}", file=sys.stderr)
        print(f"RareIQ Update 13 failed: {exc}", file=sys.stderr)
        return 1
    print("RareIQ 6.4 Update 13 installed successfully.")
    print(f"Pre-update backup: {backup}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
